namespace Meziantou.Framework.Markdown.Parsing;

/// <summary>
/// The shortcodes and the smileys of the emoji extension. EmojiShortcodes.g.cs is generated by
/// <c>tools/Meziantou.Framework.HtmlToMarkdown.Emoji.Generator</c>: the shortcodes of GitHub, and the smileys of its
/// <c>Smileys.cs</c>, whose emoji come from the names of Unicode. The arrows are written here.
/// </summary>
internal static partial class EmojiData
{
    public static Dictionary<string, string> GetDefaultEmojiShortcodeToUnicode()
    {
        var shortcodes = GetGitHubShortcodes();
        foreach (var (_, shortcode, arrow) in Arrows)
        {
            shortcodes[shortcode] = arrow;
        }

        return shortcodes;
    }

    public static Dictionary<string, string> GetDefaultSmileyToEmojiShortcode()
    {
        var smileys = GetUnicodeSmileys();
        foreach (var (smiley, shortcode, _) in Arrows)
        {
            smileys[smiley] = shortcode;
        }

        return smileys;
    }

    // The arrows, which are not emoji: their shortcodes are the ones of Meziantou.Framework.Markdown 1.x. The mnemonics ->, <-,
    // => and <= are the ones of RFC 1345, which writes <> and == for the arrows of both directions: <-> and <=> are used
    // instead, as <> and == are common in text and in code.
    private static readonly (string Smiley, string Shortcode, string Arrow)[] Arrows =
    [
        ("<-", ":custom_arrow_left:", "←"), // LEFTWARDS ARROW
        ("->", ":custom_arrow_right:", "→"), // RIGHTWARDS ARROW
        ("<->", ":custom_arrow_left_right:", "↔"), // LEFT RIGHT ARROW
        ("<=", ":custom_arrow_left_strong:", "⇐"), // LEFTWARDS DOUBLE ARROW
        ("=>", ":custom_arrow_right_strong:", "⇒"), // RIGHTWARDS DOUBLE ARROW
        ("<=>", ":custom_arrow_left_right_strong:", "⇔"), // LEFT RIGHT DOUBLE ARROW
    ];
}
